  bMe = `Fjern styring`,
  xMe = `Rediger styring`,
  SMe = `Indstillinger`,
  CMe = `Vælg en styring for %1$s`,
  wMe = `Vælg en tilstand for %1$s`,
  TMe = `Bevæger et virtuelt joystick ved at bruge din trackpadposition til direkte at styre, hvor langt det bevæges.`,
  EMe = `Bevæger et virtuelt joystick ved at bruge din gyroposition til direkte at styre, hvor langt det bevæges.`,
  DMe = `Flytter musemarkøren med en jævn hastighed lige så længe, du holder en bevægelse, og hurtigere, jo mere du skubber.`,
  OMe = `Flytter musemarkøren på samme måde, som du bevæger dig på trackpadden, ligesom en trackpad på en bærbar computer.`,
  kMe = `Den gamle tilstand til at bruge joystick som mus – beholdt af hensyn til konfigurationer, som allerede bruger den.`,
  AMe = `Ændrer controllerens bevægelse til musebevægelser, så du sigter ved at vippe den.`,
  jMe = `Sender input fra kamerapinden, hvor den skubbede afstand bestemmer, hvor hurtigt kameraet drejer sig.`,
  MMe = `Ændrer controllerens bevægelse til input fra kamerapinden – for spil, der læser en styrepind fremfor en mus.`,
  NMe = `Ændrer controllerens bevægelse til styrepindsudslag, som om du skubbede styrepinden den afstand.`,
  PMe = `Tilknytter trackpadden til et område på skærmen, så et punkt på trackpadden altid peger på det samme sted.`,
  FMe = `Sender en kameravinkel direkte til spillet – for spil, der understøtter det, i stedet for muse- eller styrepindsbevægelsen, som andre tilstande skaber.`,
  IMe = `Gør, at styringen ikke gør noget, mens dette er valgt.`,
  LMe = `Sender joystickinput til spillet, men læser trackpadbevægelse som en mus. For spil, der forventer en styrepind for at sigte eller flytte en markør.`,
  RMe = `Sender joystickinput til spillet, men læser gyrobevægelse som en mus. For spil, der forventer en styrepind for at sigte eller flytte en markør.`,
  zMe = `Svirp styrepinden i en retning for at rette kameraet den vej – bliv ved med at dreje styrepinden for at dreje kameraet med samme grad.`,
  BMe = `Ingen styringer på denne controller kan bruges til denne handling i dette handlingssæt. Angiv en tilstand for den styring, du vil have på dens egen side først.`,
