  $Re = `Tilstandsskift (%1$s)`,
  eze = `%1$s (tilstandsskift)`,
  tze = `Opret et tilstandsskift`,
  nze = `Flyt mus med bestemt mængde`,
  rze = `Hver gang kommandoen udløses, flyttes musen et bestemt antal pixels. Dette kan være nyttigt, når du vil have en kommando til at vende din karakters retning i et FPS-spil, eller til at klikke på en bestemt genstand i en højrekliksmenu i et managementspil.`,
  ize = `Flyt mus til position`,
  aze = `Når denne kommando udløses, flyttes musen til et bestemt sted på skærmen. Hvis du vil, kan du lade den blive på det nye sted eller vende tilbage til der, hvor den var, inden kommandoen blev udløst. På den måde kan du tildele en bestemt knap på skærmen til controllerens fysiske input.`,
  oze = `X-position`,
  sze = `Y-position`,
  cze = `Gå tilbage til forrige position, når kommandoen er slut`,
  lze = `Vælg position manuelt`,
  uze = `Start`,
  dze = `Klik med musen, eller brug %1$s for at vælge museposition. %2$s eller Escape for at gå tilbage. Brug %3$s / %4$s eller piletasterne for at skifte mellem skærmbilleder.`,
  fze = `Nulstil kamera`,
  pze = `Nulstil kamera`,
  mze = `Nulstil kameraet til horisonten ved at indstille kameraets hældning til det maksimale, vent på et billede, og nulstil derefter kameraet til horisonten. Denne handling kræver, at indstillingen "Punkter per 360°" er kalibreret i enten tilstanden "Gyro til mus" eller "Svirp med joystick". Hvis kameraet rettes direkte mod gulvet/loftet, skal forsinkelsen øges.`,
  hze = `Send -%1$s°, vent derefter %2$s ms (svarende til %3$s FPS), og send derefter %4$s°`,
  gze = `Forsinkelse`,
  _ze = `Nulstillingsvinkel for horisont`,
  vze = `Drej kameraet %1$s°`,
  yze = `Drej kameraet %1$s°`,
  bze = `Denne handling drejer kameraet horisontalt med %1$s° ved at sende musepixels svarende til %1$s° under drejningen. Indstillingen "Punkter per 360°" bestemmer, hvor mange pixels det er, så handlingen kan bruges sammen med tilstandene "Gyro til mus" eller "Svirp med joystick".`,
  xze = `Tip: For at konfigurere indstillingen "Punkter per 360°" rigtigt per spil skal du indstille "Rotationsvinkel" til 360°.
 Tryk på knappen "Drej kameraet 360°" i spillet. Du bør derefter se en en hel omdrejning på 360°.
 Hvis du ikke vender i den oprindelige retning efter rotationen, kan du justere indstillingen "Punkter per 360°" fra controllerens hurtigindstillinger og gentage processen, indtil kameraet roterer nøjagtigt 360°.
 Nu vil indstillingerne "Gyro til mus", "Svirp med joystick", "Nulstil kamera" og "Drej kameraet i retning" også være nøjagtige.`,
  Sze = `Rotationsvinkel`,
  Cze = `Rotationsvarighed`,
  wze = `Vend i retning`,
  Tze = `Drej kameraet i retning`,
  Eze = `Drej kameraet for at vende i samme retning som inputenheden/trackpaden/retningsknappen/knapperne. Justér drejningsvarigheden for at gøre drejningen hurtigere eller længere. Handlingen kræver, at indstillingen "Punkter per 360°" kalibreres enten i tilstanden gyro til mus eller svirp med joystick.`,
  Dze = `Retningens kilde`,
  Oze = `Brug sidste retning, hvis det er en dødszone`,
  kze = `Drejningsvarighed`,
